pub fn compiler_directing_descriptor(
    kind: CompilerDirectingKind,
) -> &'static CompilerDirectingDescriptor {
    COMPILER_DIRECTING_STATEMENTS
        .iter()
        .find(|entry| entry.kind == kind)
        .expect("generated directing kind")
}

